update public.paginas
set titulo = 'Regras do vôlei de areia - quarteto Unidos',
    corpo = E'# O formato do grupo\n\nQuatro de cada lado, na areia, quadra de 16 m por 8 m.\n\n# Contagem\n\n- Set até **15 pontos**, com dois de vantagem.\n- Melhor de um. Quem ganhar o set ganha a partida.\n- Ponto em toda jogada, saque de quem ganhou o ponto.\n\n# Toques\n\n- Três toques por equipe antes de devolver a bola.\n- **O bloqueio NÃO conta como toque.** Bloqueou, ainda sobram três.\n- Quem bloqueia pode tocar de novo em seguida.\n- O mesmo jogador não toca duas vezes seguidas fora essa situação.\n\n# O que a areia proíbe\n\n- **Largada de dedo aberto.** Para colocar a bola, use crock, a mão fechada ou a mão espalmada, sem digitais.\n- Levantada de toque só atravessa a rede se sair perpendicular aos ombros de quem levantou (só pode passar de toque se for reto para frente ou para trás).\n- Segurar, conduzir ou acompanhar a bola no toque.\n\n# Faltas de sempre\n\n- Encostar na rede durante a jogada.\n- Invadir a quadra adversária por baixo da rede atrapalhando o adversário.\n- Atacar a bola de saque perto da rede.\n\n# Vento, sol e bom senso\n\nNa areia o vento é parte do jogo: a bola vai voltar, vai cair na sua mão e vai fugir dela.\n\n# Bola no teto\n\nSe a bola bater no teto e/ou na corda de aço estrutural mas não passar para o outro lado da rede, segue jogo, se passar, ponto para o adversário.'
where slug = 'regras-do-volei';
